// Offline support. On install, downloads every file of the app (listed in
// offline-manifest.js, generated by tools/build_offline.py) into the Cache API,
// then serves the app from there with or without a connection.
importScripts('offline-manifest.js'); // defines self.OFFLINE_VERSION and self.OFFLINE_ASSETS

const CACHE_PREFIX = 'hora-del-cuento-';
const CACHE = CACHE_PREFIX + self.OFFLINE_VERSION;
const CONCURRENCY = 6;

async function notify(message) {
  const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  clients.forEach((client) => client.postMessage(message));
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      const queue = [...self.OFFLINE_ASSETS];
      const total = queue.length;
      let done = 0;
      async function worker() {
        while (queue.length) {
          const url = queue.shift();
          // Files already saved by an interrupted install of this same version are kept.
          if (!(await cache.match(url))) {
            const response = await fetch(url, { cache: 'reload' });
            if (!response.ok) throw new Error(`${url}: ${response.status}`);
            await cache.put(url, response);
          }
          done += 1;
          notify({ type: 'offline-progress', done, total });
        }
      }
      await Promise.all(Array.from({ length: CONCURRENCY }, worker));
      await self.skipWaiting();
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE).map((key) => caches.delete(key)));
      await self.clients.claim();
      notify({ type: 'offline-ready' });
    })()
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== location.origin) return;

  const scopePath = new URL(self.registration.scope).pathname;
  if (request.mode === 'navigate' && (url.pathname === scopePath || url.pathname === `${scopePath}index.html`)) {
    event.respondWith(fromCache('index.html', request));
  } else if (request.headers.has('range')) {
    event.respondWith(rangeFromCache(request));
  } else {
    event.respondWith(fromCache(request, request));
  }
});

async function fromCache(key, request) {
  const cached = await caches.match(key, { cacheName: CACHE, ignoreSearch: true });
  return cached || fetch(request);
}

// <audio> asks for byte ranges, and Safari only plays/seeks with a 206 answer,
// so slice the requested bytes out of the cached file.
async function rangeFromCache(request) {
  const cached = await caches.match(request.url, { cacheName: CACHE, ignoreSearch: true });
  if (!cached) return fetch(request);

  const blob = await cached.blob();
  const size = blob.size;
  const [, first, last] = /bytes=(\d*)-(\d*)/.exec(request.headers.get('range')) || [];
  let start = first ? Number(first) : 0;
  let end = last ? Math.min(Number(last), size - 1) : size - 1;
  if (!first && last) {
    start = Math.max(0, size - Number(last)); // suffix range: the last N bytes
    end = size - 1;
  }
  if (start > end) {
    return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${size}` } });
  }
  return new Response(blob.slice(start, end + 1), {
    status: 206,
    headers: {
      'Content-Type': cached.headers.get('Content-Type') || 'audio/mpeg',
      'Content-Range': `bytes ${start}-${end}/${size}`,
      'Content-Length': String(end - start + 1),
      'Accept-Ranges': 'bytes',
    },
  });
}
